/************************************************************/
/*My Shadow Text*/
/************************************************************/
function stext(txt,x,y,s,r,shx,shy){
    pushMatrix();
        translate(x,y);
        rotate(r);
        fill(173, 173, 173);
        textSize(s);
        text(txt,shx,shy);
        fill(255, 255, 255);
        text(txt,0,0);
    popMatrix();
}

/************************************************************/
/*Graphics*/
/************************************************************/
function TreeTri(x,y,s,cc){
    var i = 0;
    for(i = 0;i<360;i+=45){
        pushMatrix();
            translate(x,y);
            rotate(i);
            scale(s);
            noStroke();
            fill(cc);
            triangle(-130,20,130,20,0,188);
            rect(0,0,20,20);
        popMatrix();
    }    
}//Triangle function for the trees
function BushTri(x,y,s,cc,cc2){
    var i;
    for(i = 0;i<360;i+=45){
        pushMatrix();
            translate(x,y);
            scale(s);
            noStroke();
            fill(cc);
            rotate(i);
            ellipse(49,12,60,60);
            ellipse(0,0,60,60);
            rotate(-i);
        
            fill(cc2);
            stroke(54, 54, 54);
            strokeWeight(4);
            ellipse(37,0,30,30);
            ellipse(-38,9,30,30);
            ellipse(0,-33,24,24);
            ellipse(6,40,25,25);
        popMatrix();

    }    
}//Circle function for the bushes
function RockTri(x,y,s,cc,r){

        pushMatrix();
            translate(x,y);
            scale(s);
            noStroke();
            fill(cc);
            rect(-50,-30,100,51);
            triangle(-50,20,50,20,0,53);
            triangle(-50,-30,50,-30,0,-65);
        popMatrix();

        
}//Square function for  the rock
function Land(cc){
        var ii = 0;
        var jj = 0;
        background(cc);
        for (ii = -50; ii < width + 50; ii += 50) {
            for (jj = -50; jj < height+ 50; jj += 50) {
                stroke(0,0,0,4);
                noFill();
                strokeWeight(2);
                rect(ii, +jj, 99, 100);
            }
        }    
}
function WallTri(x,y,s,cc,r){
    var j = 0;
    for(j = 0;j<360;j+=45){
        pushMatrix();
            translate(x,y);
            scale(s);
            noStroke();
            fill(cc);
            rotate(j+r);
            triangle(-70,20,62,57,5,85);
            ellipse(0,0,100,104);
        popMatrix();

    }    
}
function ear(x,y,s,s2,r,fills,strokes){
    pushMatrix();
        translate(x,y);
        scale(s,s2);
        rotate(r);

        pushStyle();
        fill(fills);
        stroke(strokes);
        strokeWeight(4);
        beginShape();
        curveVertex(-48,-17); curveVertex(-34,-5); curveVertex(-16,5); curveVertex(-27,20); curveVertex(-35,33); curveVertex(-46,31); curveVertex(-51,6); curveVertex(-48,-16); curveVertex(-35,-5); curveVertex(-16,5);
        endShape();
        popStyle();
    
    popMatrix();           

}//ear for the wolf
function Horn(x,y,s,s2,r){
    pushMatrix();
        pushStyle();
        translate(x,y);
        scale(s,s2);
        rotate(r);
        fill(199, 177, 149);
        stroke(51, 51, 51);
        strokeWeight(4);
        beginShape();
            curveVertex(-48,-32); curveVertex(-33,-32); curveVertex(-32,-13); curveVertex(-55,-11); curveVertex(-76,-34); curveVertex(-78,-61); curveVertex(-48,-32); curveVertex(-33,-32); curveVertex(-32,-13); 
        endShape();
        popStyle();
    popMatrix();    
}
function LdWings(x,y,s,s1,r){
    pushMatrix();
    translate(x,y);
    scale(s,s1);
    rotate(r);
        beginShape();
        vertex(250, 262);
        vertex(244, 330);
        vertex(280, 391);
        vertex(213, 363);
        vertex(218, 396);
        vertex(172, 359);
        vertex(168, 380);
        vertex(133, 345);
        vertex(134, 430);
        vertex(104, 355);
        vertex(82, 292);
        vertex(92, 264);
        vertex(124, 235);
        vertex(150, 259);
        vertex(175, 284);
        vertex(209, 286);
        endShape(CLOSE);    
    
    popMatrix();
}
function Head(x,y,s,s1,r,colors){
    pushMatrix();
    translate(x,y);
    scale(s,s1);
    rotate(r);
    noStroke();
    fill(colors);
    pushStyle();
    beginShape();
    curveVertex(49,-13); curveVertex(62,-43); curveVertex(43,-1); curveVertex(29,7); curveVertex(23,-5); curveVertex(32,-62); curveVertex(54,-106); curveVertex(87,-130); curveVertex(128,-101); curveVertex(157,-40); curveVertex(162,11); curveVertex(136,-16); curveVertex(120,-45); curveVertex(136,-16); curveVertex(136,48); curveVertex(54,35); curveVertex(49,-13); curveVertex(41,-66); curveVertex(43,-1);
    endShape();
    popStyle();
    popMatrix();
}
function DrawDragon(c1,c2,c3,c4){
pushMatrix();
    translate(222,246);
    
    
    
    Head(-87,-68,0.89,1.2,0,c1);    

    stroke(0, 0, 0);
    strokeWeight(3);
    fill(c1);
    ellipse(-9,-167,72,127);
    
    fill(c2);
    stroke(51, 38, 38);
    strokeWeight(5);
    
    LdWings(-182,-448,0.5,1.4,0);
    LdWings(182,-448,-0.5,1.4,0);
    
    fill(c1);
    strokeWeight(3);
    pushMatrix();
        translate(-308,-300);
        beginShape();
        vertex(339, 353);
        vertex(324, 458);
        vertex(304, 486);
        vertex(277, 481);
        vertex(237, 441);
        vertex(210, 437);
        vertex(235, 429);
        vertex(206, 420);
        vertex(246, 419);
        vertex(264, 436);
        vertex(281, 451);
        vertex(296, 438);
        vertex(285, 411);
        endShape(CLOSE);
    popMatrix();


    
    fill(c2);
    strokeWeight(2);
    ellipse(0,0,132,250);
    Head(-81,-97,0.82,1,0,c3);
    Head(-79,-95,0.8,1,0,c2);
    
    noStroke();
    fill(c4);
    ellipse(-24,-167,15,15);
    ellipse(10,-167,15,15);

    fill(c4,50);
    ellipse(-17,-202,7,15);
    ellipse(-2,-202,7,15);
    var k = 0;
    for(k = 0;k<9;k++){
        pushMatrix();
            translate(-3,k*25-94);
            quad(-30+k*2,10,0,-13,30-k*2,10,0,5);
        popMatrix();
    }
    
    fill(255, 211, 79);
    ellipse(-25,-170,7,7);
    ellipse(7,-170,7,7);    
    
    fill(255, 255, 255);
    arc(6,-220,7,4,-180,0);
    arc(12,-215,7,4,-180,0);
    arc(-5,-227,7,4,-229,-54);
    arc(-16,-227,7,4,-229,-54);
    arc(-31,-212,7,4,-229,-54);
    arc(-24,-222,7,4,-275,-104);
popMatrix();    
}



