/************************************************************/
/*Collisions*/
/************************************************************/
function rectorec(x1, y1, x2, y2, w1, h1, w2, h2) {
    return (x1 + w1 > x2 && x1 < x2 + w2 && y1 + h1 > y2 && y1 < y2 + h2);
}

function ptorect(x1, y1, x2, y2, w2, h2) {
    return (x1 > x2 && y1 > y2 && x1 < x2 + w2 && y1 < y2 + h2);
}

function ctorect(cx, cy, cr, rx, ry, rw, rh) {
    var TsX = cx;
    var TsY = cy;

    if (cx < rx) {
        TsX = rx;
    } else
    if (cx > rx + rw) {
        TsX = rx + rw;
    }
    if (cy < ry) {
        TsY = ry;
    } else
    if (cy > ry + rh) {
        TsY = ry + rh;
    }

    var distX = cx - TsX;
    var distY = cy - TsY;
    var distance = sqrt((distX * distX) + (distY * distY));

    return (distance <= cr / 2);

}

function inrange(x,y,x1,y1,mapX,mapY) {
    return (x>x1-mapX&&x<x1+mapX&&y>y1-mapY&&y<y1+ mapY);
}

