/************************************************************/
/*Object Constructor*/
/************************************************************/

function Objs(x,y,s,r,types,objs){
    this.x = x;
    this.y = y;
    this.s = s;
    this.r = r;
    this.types = types;
    this.objs = objs;
    this.ded = false;
    this.health = 300;
    
    this.id = random(0,1000000000);
    this.PTO = 0;
    
    //Damage to your enemies
    this.Damage = "";
    this.poison = 0;
    
    //When your hit
    this.shake = 0;
    this.shakey = 0;
    
    this.setup = false;//Setting it up
    this.approved = false;
    this.checked = true;
    this.wood= 0;
    this.rock =0;
    this.slot = 0;
    
    this.windTme = 1;
    
}
Objs.prototype.draw = function(){
    if(this.setup===false){
        
       if(this.objs==="spike"){
            this.slot = 4;
            switch(this.types){
                //Spike lvl 1
                case 1:
                    this.Damage = 20;
                    this.health = 350;
                    this.wood= 20;
                    this.rock =5;
                break;
                //Spike lvl 2
                case 2:
                    this.Damage = 30;
                    this.health = 500;
                    this.wood= 30;
                    this.rock =10;
                break;
                //Poison spike 
                case 3:
                    this.Damage = 30;
                    this.poison = 5;
                    this.health = 600;
                    this.wood= 40;
                    this.rock =15;
                break;
                //Spike lvl 3
                case 4:
                    this.Damage = 45;
                    this.health = 500;
                    this.wood= 50;
                    this.rock =20;
                break;
            }
        }
       if(this.objs==="wall"){
            this.slot = 3;
            switch(this.types){

                //wall
                case 1:
                    this.health = 380;
                    this.wood= 10;
                    this.rock =0;
                break;
                //stone wall
                case 2:
                    this.health = 900;
                    this.wood= 0;
                    this.rock =25;
                break;
                //castle wall
                case 3:
                    this.health = 1500;
                    this.wood= 0;
                    this.rock =35;
                break;
            }
        } 
       if(this.objs==="trap"||this.objs==="boost"){
            this.slot = 6;
            switch(this.types){
                //Trap
                case 0:
                    this.health = 500;
                    this.wood= 30;
                    this.rock =30;
                break;
                //Boost
                case 1:
                    this.health = 150;
                    this.wood= 5;
                    this.rock =20;
                break;
            }
        }
       if(this.objs==="Windmill"){
            this.slot = 5;
            switch(this.types){
                case 1:
                    this.health = 400;
                    this.wood= 50;
                    this.rock =10;
                break;
                case 2:
                    this.health = 500;
                    this.wood= 60;
                    this.rock =20;
                break;
                case 3:
                    this.health = 800;
                    this.wood= 90;
                    this.rock =50;
                break;
            }
        }     
       if(this.objs === "Platformings"){
           switch(this.types){
               //Wood Platform
                case 1:
                    this.health = 300;
                    this.wood= 20;
                    this.rock =5;
                break;
                //Healing Pad
                case 2:
                    this.health = 400;
                    this.wood= 30;
                    this.rock =5;
                break;
               //Poison Pad
                case 3:
                    this.health = 500;
                    this.wood= 30;
                    this.rock =30;
                break;
                
               //Teleporter
                case 4:
                    this.health = 200;
                    this.wood= 70;
                    this.rock =70;
                break;
            }
       }
       
        this.setup = true;
        this.checked = false;
    } 
    
    if(this.checked === true&&this.setup === true){
    
    if(this.objs === "spike"){
        Spikes(this.x+this.shake,this.y+this.shakey,this.s,this.r,this.types);
        if(this.types===4){
            this.r+=6;
        } 
    } else
    if(this.objs === "trap"){
        PitTrapAndBoost(this.x+this.shake,this.y+this.shakey,this.s,this.r,1);
    } else
    if(this.objs === "wall"){
        Barrier(this.x+this.shake,this.y+this.shakey,this.s,this.r,this.types);
    } else
    if(this.objs === "Windmill"){
        Objects("Windmill",this.x+this.shake,this.y+this.shakey,this.s+30,this.r);
        this.r+=3*this.types;
        
        

    } else
    if(this.objs === "boost"){
       PitTrapAndBoost(this.x+this.shake,this.y+this.shakey,this.s,this.r,2);

       
    } else
    if(this.objs === "Platformings"){
        Platforming(this.x+this.shake,this.y+this.shakey,this.s,this.r,this.types);
    }
    
    }
};
Objs.prototype.update = function(){
    this.shake*= 0.92;
    this.shakey*=0.92;    
    this.windTme-=0.02;
    var job = 0;
    for(job = objs.length-1;job>=0;job--){
        if(dist(this.x,this.y,objs[job].x,objs[job].y)<objs[job].s/2+this.s/2-20&&this.id!==objs[job].id){
            this.ded = true;

        }
    }
    var i1 = 0;
    for(i1 = 0;i1<bs.length;i1++){

        if(dist(this.x,this.y,bs[i1].x,bs[i1].y)<bs[i1].s/2-25+this.s/2){
            this.ded = true;

        }
    }   
    var i2 = 0;
    for(i2 = 0;i2<tr.length;i2++){

        if(dist(this.x,this.y,tr[i2].x,tr[i2].y)<tr[i2].s/2+this.s/2-60){
            this.ded = true;

        }
    }   
    var i3 = 0;
    for(i3 = 0;i3<rk.length;i3++){
        if(dist(this.x,this.y,rk[i3].x,rk[i3].y)<rk[i3].s/2+this.s/2-30){
            this.ded = true;

        }
    }   
    var i4 = 0;
    for(i4 = 0;i4<rks.length;i4++){
        if(dist(this.x,this.y,rks[i4].x,rks[i4].y)<rks[i4].s/2+this.s/2-30){
            this.ded = true;

        }
    }   
    var i5 = 0;
    for(i5 = 0;i5<wat.length;i5++){
        if(ctorect(this.x,this.y,this.s/5,wat[i5].x,wat[i5].y+5,wat[i5].s,wat[i5].s-10)&&this.objs!=="Platformings"&&this.types!==1){
            this.ded = true;

        }
    }
};//collisions

