function animals(x,y,s,r,animal,health,name){
    this.x = x;
    this.y = y;
    this.s = s;
    this.ss = this.s/3;
    this.r = r;
    this.animal = animal;
    this.health = health;
    this.name = name;
    this.money = 200;
    this.food = 50;
    this.xp = 0;
    this.mxhealth = 400;
    this.rtme=round(random(0,20));//
    this.actr=round(random(0,360));//choosing rotation
    this.speed=2;
    this.maxSpd = 3;
    this.actSpd = 3;
    this.pause=0;
    
    this.waterR= 0;
    this.trapped = 0;
    
    this.runTme = 0;
    this.RunRot = 0;
    this.bounce = 0;
    this.pHit = 0;
    this.turnSpd = 2;
    this.NormalSpd = 2;
    
    this.attackR = 0;
    
    this.Load = false;
    
    this.colliding = 0;
    
    this.poisoned = 0;
    
    this.dragonRevive = 60;
    this.startTimer = false;
    this.bigRange = 0;
    this.dragDam = 0;
    this.hittmes = 0;
}
animals.prototype.draw = function(){
    if(this.Load===false){
        this.mxhealth = this.health;
        
        this.Load = true;
    }
    pushMatrix();
        translate(this.x,this.y);
        rotate(this.r);
        if(this.animal==="pig"){
            this.maxSpd = 3;
            this.food = 80;
            this.money = 200;
            this.turnSpd = 2;
            this.ss = this.s/3;
            this.xp = 300;
            this.bigRange =0;
            image(Sprites.Pig,-this.s/2,-this.s/2,this.s,this.s);
        }
        if(this.animal==="sheep"){
            this.maxSpd = 3;
            this.food = 100;
            this.money = 1000;
            this.ss = this.s/3+10;
            this.turnSpd = 3;
            this.xp = 600;
            this.bigRange =0;
            image(Sprites.Sheep,-this.s/4,-this.s/4,this.s/2,this.s/2);
            fill(0,0,0,60);
           // ellipse(0,0,this.ss,this.ss);
        }        
        if(this.animal==="cow"){
            this.maxSpd = 3;
            this.maxSpd = 3;
            this.food = 50;
            this.money = 150;
            this.turnSpd = 2;
            this.ss = this.s/3;
            this.xp = 400;
            this.bigRange  =0;
            image(Sprites.Cow,-this.s/2,-this.s/2,this.s,this.s);
        }
        if(this.animal==="Wolf"){
            this.maxSpd = 5;
            this.food = 200;
            this.money = 500;
            this.turnSpd = 4;
            this.ss = this.s/3;
            this.xp = 400;
            this.bigRange =0;
            image(Sprites.Wolf,-this.s/2,-this.s/2,this.s,this.s);         
            
        }   
        if(this.animal==="Bull"){
            this.maxSpd = 5;
            this.food = 100;
            this.money = 1000;
            this.turnSpd = 1.3;
            this.ss = this.s/3;
            this.xp = 1000;
            this.bigRange =0;
            image(Sprites.Bull,-this.s/2,-this.s/2,this.s,this.s);         
            
        }      
        if(this.animal==="dragon"){
            this.maxSpd = 8;
            this.food = 300;
            
            this.turnSpd = 6;
            this.ss = this.s/3;
            this.xp = 3000;
            this.trapped = -100;
            this.bigRange =30;
            
            if(this.s>=395){
                this.dragDam =25;
                this.money = 8000;
            image(Sprites.reddragon,-this.s/2,-this.s/2,this.s,this.s);        }
            if(this.s===350){
                this.dragDam =20;
                this.money = 5000;
            image(Sprites.greendragon,-this.s/2,-this.s/2,this.s,this.s);        }
            if(this.s===300){
                this.money = 3000;
                this.dragDam =15;
            image(Sprites.yellowdragon,-this.s/2,-this.s/2,this.s,this.s);        }
        }
        fill(0,0,0,160);
      
    popMatrix(); 
    
    textSize(20);
    fill(48, 48, 48);
    text(this.name,this.x-3,this.y-this.s/3.5+2);
    fill(240, 240, 240);
    text(this.name,this.x,this.y-this.s/3.5);
    
    fill(48, 48, 48);
    noStroke();
    rectMode(CENTER);
    rect(this.x,this.y+this.s/3.5,this.mxhealth*106/this.mxhealth,10,7);
    rectMode(CORNER);
    fill(163, 35, 35);
    rect(this.x-50,this.y+this.s/3.5-3,this.health*100/this.mxhealth,6,5);
};
animals.prototype.circleCol= function(x,y,d){
  if(dist(this.x, this.y, x, y) <= this.ss/2 + d/2){
    var a = atan2(this.y - y, this.x-x);
    var dis = dist(this.x, this.y, x, y)+7;
    var s = d-dis;
    
    if(this.animal!=="dragon"){
        this.x += cos(a)*s/13;
        this.y += sin(a)*s/13;
    } 
    else{
      this.x += cos(a)*s/9;
        this.y += sin(a)*s/9;  
    }
  }

};
animals.prototype.move = function(){
    this.hittmes-=1;
    if(this.startTimer === false){
    this.x = constrain(this.x,0+this.ss/2,MapSize-this.ss/2);
    this.y = constrain(this.y,0+this.ss/2,MapSize-this.ss/2);
    }
    
    this.actSpd = this.bounce+this.pHit;
    
    if(this.animal!=="dragon"){
        this.rtme-=0.03;
    } else{
        this.rtme-=0.06;
    }
    this.pause*=0.94;
    this.waterR*=0.98;
    this.runTme-=0.03;
    this.coliding -=1;
    this.bounce*=0.93;
    this.pHit*=0.96;
    this.trapped--;
    this.poisoned -=0.02;
 
    if(this.poisoned>0){
        this.health-=0.5;
    }
    
    this.bounce = constrain(this.bounce,0,14); 
    
    if(this.trapped<=0&&this.animal!=="Bull"){
        this.x+=sin(this.RunRot) *this.actSpd;
        this.y-= cos(this.RunRot) *this.actSpd;  
    } 
    else{
        this.x+=sin(this.RunRot) *this.bounce/25;
        this.y-= cos(this.RunRot) *this.bounce/25;          
    }
    if(this.rtme<=0){
        this.rtme = round(random(0,20));
        this.actr = round(random(0,360));
        this.pause=random(0,7);
    }
    if(this.pause<=0.2){
            if(this.bounce<1){
            this.x+=sin(this.r) * (this.speed-this.waterR);
            this.y -= cos(this.r) *(this.speed-this.waterR); 
            }
        if(this.r-6>this.actr&&this.trapped<=0){
            this.r-=this.turnSpd;
        }
        if(this.r+6<this.actr&&this.trapped<=0){
            this.r+=this.turnSpd;
        }
    } 

   if(this.actr<=-360){
       this.actr+=360;
   }
   if(this.actr>=360){
       this.actr-=360;
   }    
    if(this.runTme>0&&this.trapped<=0&&this.animal!=="Wolf"&&this.animal!=="Bull"){
        this.speed = this.maxSpd+2;
        this.actr = this.RunRot;
    } else if(this.trapped<=0){
        this.speed = this.maxSpd;
    }
    
    if(this.startTimer){
        this.dragonRevive -=0.03;
        if(this.dragonRevive<=0){
            this.dragonRevive = 60;
            this.startTimer = false;
            this.x =  random(MapSize/2-100,MapSize/2+100);
            this.y = random(MapSize/1.3-200,MapSize/1.3);
        }
    }
    


};
animals.prototype.collide = function(){
    var i;
    for(i = 0;i<objs.length;i++){
    
    if(dist(this.x,this.y,objs[i].x,objs[i].y)<this.ss/2+objs[i].s/2&&objs[i].checked=== true&&objs[i].setup===true){
        switch(objs[i].objs){    
            case "spike":
                
                this.circleCol(objs[i].x, objs[i].y,objs[i].s);
                if(this.bounce<14){this.bounce+=7;}
                if(objs[i].types === 3){
                    this.poisoned = 10;
                }
                if(this.animal!=="dragon"){
                this.health -=objs[i].Damage;
                this.RunRot = atan2(this.y-objs[i].y,this.x-objs[i].x)+90;
                this.actr = atan2(this.y-objs[i].y,this.x-objs[i].x)+90;
                hit.push({x:this.x,y:this.y+random(-30,30),s:70,txt:objs[i].Damage,type:0});
                }
            break;
            case "trap":
                if(dist(this.x,this.y,objs[i].x,objs[i].y)<this.ss/4+objs[i].s/2&&this.animal!=="dragon"){
                this.trapped = 2;
                this.speed*=0.9;
                }
            break;
            case "wall":
                this.circleCol(objs[i].x, objs[i].y,objs[i].s*1.5);
            break;
            case "Windmill":
                this.circleCol(objs[i].x, objs[i].y,objs[i].s*1.5);
            break;
            case "boost":
            if(dist(this.x,this.y,objs[i].x,objs[i].y)<this.s/2+objs[i].s/2.5){
            this.RunRot = objs[i].r;
            this.bounce = 20;
        }
            break;
            case "Platformings":
                switch(objs[i].types){
                    case 2:
                        this.health+=0.5;
                    break;
                    case 3:
                        this.poisoned = 5;
                    break;
                    case 4:
                        this.x = round(random(0,MapSize));
                        this.y = round(random(0,MapSize));
                    break;
                }
            break;
            
            
        }
    }
    }    
    var ic1 = 0;
    var ic2 = 0;
    var ic3 = 0;
    var ic4 = 0;
    for(ic1 = 0;ic1<tr.length;ic1++){
        this.circleCol(tr[ic1].x, tr[ic1].y,tr[ic1].s/1.6);//collide
    }
    for(ic2 = 0;ic2<rk.length;ic2++){
        this.circleCol(rk[ic2].x, rk[ic2].y,rk[ic2].s/1.1);//collide
    }
    
    for(ic3 = 0;ic3<rks.length;ic3++){
        if(this.animal!=="dragon"){
            this.circleCol(rks[ic3].x, rks[ic3].y,rks[ic3].s/1.1);
        } else{
            this.circleCol(rks[ic3].x, rks[ic3].y,rks[ic3].s*1.2);
        }
    }
    for(ic4 = 0;ic4<bs.length;ic4++){
        this.circleCol(bs[ic4].x, bs[ic4].y,bs[ic4].s+6);//collide
    }   
    var ic5 = 0;
    for(ic5 = 0;ic5<wat.length;ic5++){
        if(ctorect(this.x,this.y,this.s/2,wat[ic5].x,wat[ic5].y+40,wat[ic5].s,wat[ic5].s-80)&&this.trapped<=0 ){
            this.x+=4;
            this.waterR = 1;
        }   
    }        
};
animals.prototype.revive = function(){

        if(this.animal!=="dragon"){
            this.health = this.mxhealth;
            this.x = round(random(0,MapSize));
            this.y = round(random(0,MapSize));
        }
        else{
            this.x = MapSize*200;
            this.y = MapSize*200;
            this.health = this.mxhealth;
        }
};

