function Weapons(x,y,s,r,types,jewel){
    
    pushMatrix();
        translate(x,y);
        scale(s);
        rotate(r);
        
        switch(types){
            case "Shield":
                Shield();
            break;
            case "Polearm":
                Polearm(jewel);
            break;
            case "Hammer":
                Axe(1,jewel);
            break;
            case "Mallet":
                Hammer(1,jewel);
            break;
            case "GreatMallet":
                Hammer(2,jewel);
            break;
            case "HandAxe":
                Axe(2,jewel);
            break;
            case "GreatAxe":
                Axe(3,jewel);
            break;
            case "Stick":
                Stick(jewel);
            break;
            case "ShortSword":
                Sword(1,jewel);
            break;
            case "Katana":
                Sword(2,jewel);
            break;
            case "Bat":
                Bat(jewel);
            break;
            case "Dagger":
                Dagger(jewel);
            break;
        }
        
    popMatrix();
}
