function Player(x, y, s, r) {
    this.x = x; //Players Coordinates
    this.y = y; //Players Coordinates
    this.s = s; //Players size (radius)
    this.r = r; //Players Rotation
    this.Rrot = 0;//your rotation as well
    this.lock = false;//If your rotation is locked
    this.cc = colorPal[3]; //Your Color
    this.name = "Corin Fist"; //Your Name
    
    this.hat = 0;
    this.tail = 0;
    
    this.slots = [
    "Stick",//First hand weapon
    "Mallet",//Mallet gun and such
    1,//Food
    1,//Barrier
    1,//Spike
    1,//Windmill
    1,//Trap and boost
    1,// Heal Pad, teleport, poison pad,platform,mine,bush,tree
    ]; //What is in your slots
    
    this.slotSwitchTme = 0;//how fast you can switch slots
    this.slot1Jewel = 1; //what level your melee is at
    this.slot2Jewel = 1; //what level your hammer is at
    this.s1c= 0; //How much materials you have collected
    this.s2c = 0;//How much materials you have collected
    
    
    this.ExtraDamage = 0;
    this.Damage = 20; // your damage
    this.matDmg = 0; // damage to items
    this.yourSlot = 0;//which slot you are in
    
    this.fighting = false; //if you are hitting
    this.fasterFight = 0;
    this.autoFight = false;//automatically fight
    this.autoOn = false;//conditional for auto
    this.fightRot = 0;//the angle you are hitting
    this.centeredRot = 0;//Your weapons centered rotation
    this.fightSpd = 10; // the speed you are starting to hit
    this.returnSpd = 10;//when your weapon comes back
    this.collected = false; // when you want to collect items
    this.collectAmnt = 1;//collection per hit
    this.weaponSpd = 0; //overall weapon speed
    this.weaponACC = 0.8; // acceleration
    this.range = 20;//your hitbox range
    this.rebound = 5;//how much your enemies bounce back
    
    this.speed =4;//your movement speed
    this.TailSpd = 0;//Tail Speed;
    this.HatSpd = 0;//Hat Speed
    
    this.resist = 0;//movemnt resistance in snow
    this.waterR = 0;//movement resistance in water
    this.weaponResist=0;//movement resistance with weapons
    this.itemResist = 0;
    this.Xacc = 0;//your x acceleration
    this.Yacc = 0;//your Y accelleration
    this.overallAcc = 0; // overall what speed you are
     
    this.health = 100;//how much health you have
    this.healAmnt = 10;//how much you will heal
    
    this.reload = 0;//Musket reloading
    
    this.Rspd = 0;//when you are hit
    this.BoostR = 0;
    
    this.age = 1;//your age
    this.ageSwitch = 2;//age switch counter
    this.hidBoxnum = 2;
    this.wood = 0; //your wood 
    this.stone = 0; //your stone
    this.fruit = 0; //your food
    this.gold = 0;//your gold
    this.extraGold = 0;
    this.experience = 9;//your age points
    this.maxExp = 300;
    this.barSelect = 0;//what you have selected from the bar
    this.hovered = 0;//If you are over a button
    
    this.useFruit = 10;
    this.onPlank = false;
    this.poisoned = 0;//when your poisoned
    
}
Player.prototype.ShowWeapon = function(x,y,s,r,type){

    pushMatrix();
    translate(x,y);
    scale(s);
    rotate(r);
        if(type === 0||type===1){
        switch(this.slots[type]){
            case "Mallet":
                Weapons(17,3,0.70,0,"Mallet",this.slot2Jewel);
            break;
            case "Shield":
                Weapons(17,3,0.70,0,"Shield");
            break;
            case "GreatMallet":
                Weapons(17,3,0.70,0,"GreatMallet",this.slot2Jewel);
            break;
            case "Hammer":
                Weapons(17,0,0.65,0,"Hammer",this.slot1Jewel);
            break;
            case "Axe":
                Weapons(17,0,0.65,0,"HandAxe",this.slot1Jewel);
            break;
            case "GreatAxe":
                Weapons(17,0,0.65,0,"GreatAxe",this.slot1Jewel);
            break;
            case "Stick":
                Weapons(17,-2,0.65,0,"Stick",this.slot1Jewel);
            break;
            case "Bat":
                Weapons(17,-2,0.65,0,"Bat",this.slot1Jewel);
            break;
            case "Polearm":
                Weapons(17,-2,0.65,0,"Polearm",this.slot1Jewel);
            break;
            case "ShortSword":
                Weapons(17,-2,0.65,0,"ShortSword",this.slot1Jewel);             
            break;
            case "Katana":
                Weapons(17,-2,0.65,0,"Katana",this.slot1Jewel);             
            break;
            case "Dagger":
                Weapons(1,-2,0.62,0,"Dagger",this.slot1Jewel);             
            break;
        }
    } else
        if(type === 2){
            Food(30,0,1,0,this.slots[2]);
            
        }else
        if(type === 3){
            Barrier(60,0,80,0,this.slots[3]);
        } else
        if(type === 4){
            Spikes(60,0,80,22,this.slots[4]);
        } else
        if(type === 5){
            Objects("Windmill",60,0,100,0);
        } else
        if(type === 6){
            PitTrapAndBoost(60,0,90,0,1);
        }
        if(type === 7){
            PitTrapAndBoost(60,0,70,90,2);
        }
        if(type === 8){
            Platforming(60,0,70,90,this.slots[7]);
        }
    popMatrix();
    


};
