Player.prototype.circleCol= function(x,y,d){
  if(dist(this.x, this.y, x, y) <= this.s/2 + d/2){
    var a = atan2(this.y - y, this.x-x);
    var dis = dist(this.x, this.y, x, y)+this.overallAcc*1.1;
    var s = d-dis;
    this.x += cos(a)*s/13;
    this.y += sin(a)*s/13;
  }
};
