Player.prototype.ApplyItems = function(){
    
    if(this.tail === 6||this.tail === 8){
        if(this.tail === 6){ this.TailSpd = 2; }
        if(this.tail === 8){ this.TailSpd = 1; }
    } 
    else{
        this.TailSpd = 0;
    }
    
    if(this.tail ===7){
        this.health+=0.08;
    }
    
    //Hat {
    if(this.hat === 9){
        this.HatSpd = 1;
    } 
    else{
        this.HatSpd = 0;
    }

    if(this.hat === 10||this.hat === 14){
        if(this.hat === 10&&Invinsible===false){
            this.ExtraDamage = round(this.Damage/5);
            this.health-=0.05;
        }
        if(this.hat === 14){
            this.ExtraDamage = round(this.Damage/6);
            this.health+=0.08;
        }
    } 
    else{
        this.ExtraDamage = 0;
    }
    
    if(this.hat === 11){
        if(frameCount%20===0){this.gold+=2;}
    }
    
    if(this.hat === 12){
        this.fasterFight = 5;
    }
    else{
        this.fasterFight = 0;
    }
    
    if(this.hat === 13){
        this.extraGold = 2;
    }
    else{
        this.extraGold = 1;
    }   
    
    //}
    
};
