function Box(x,y,s,item){
    this.x = x;
    this.y = y;
    this.s = s;
    this.item =item;
    this.select = 0;
    this.hover = false;
    this.txt = "";
    this.descript = "";
    this.wood = 0;
    this.rock = 0;
}
Box.prototype.draw = function(){

    fill(0,0,0,50);
    noStroke();
    rect(this.x,this.y,this.s,this.s,5);
    if(this.hover===true&&clicktme>0){
        you.yourSlot = this.select;
    }
    switch(this.item){
        //melee
        case 1:
            if(you.slots[0]!=="Dagger"){
                you.ShowWeapon(this.x+27,this.y+51,0.4,-141,0);
            }
            if(you.slots[0]==="Dagger"){
                you.ShowWeapon(this.x+30,this.y+51,0.4,-90,0);
            }
                this.txt = you.slots[0];
                this.descript = "\n\nMain Melee Weapon";
            this.select = 0;
        break;
        //Hammer
        case 2:
            if(you.slots[1]==="Shield"){
                you.ShowWeapon(this.x+39,this.y+44,0.5,-141,1);
                this.txt = "Shield";
                this.descript = "\n\nProtects You from \nsmall mobs";
            } else{
            you.ShowWeapon(this.x+29,this.y+44,0.4,-141,1);
                this.txt = "Hammer";
                this.descript = "\n\nDestroy Objects";
            }
            this.select = 1;
        break;
        //Food
        case 3:
            you.ShowWeapon(this.x+25,this.y+61,0.8,-82,2);
            this.select = 2;
            this.txt = "Food";
                this.descript = "\n\nHeals your health\nCosts: "+you.useFruit+" Food";
        break;
        //wall
        case 4:
            if(this.hover === true){
                switch(you.slots[3]){
                    case 1:
                        this.wood= 10;
                        this.rock =0;
                    break;
                    case 2:
                        this.wood= 0;
                        this.rock =25;
                    break;
                    case 3:
                        this.wood= 0;
                        this.rock =35;
                    break;
                }
            }
             
            you.ShowWeapon(this.x+31,this.y+70,0.6,-93,3);
            this.txt = "Barrier";
    this.descript = "\n\nProtects your base\n"+this.wood+" Wood  | "+this.rock+" Rock";
            this.select =3;

        break;
        //Spike
        case 5:
            if(this.hover === true){
                switch(you.slots[4]){
                    case 1:
                        this.wood= 20;
                        this.rock =5;
                    break;
                    case 2:
                        this.wood= 30;
                        this.rock =10;
                    break;
                    case 3:
                        this.wood= 40;
                        this.rock =15;
                    break;
                    case 4:
                        this.wood= 50;
                        this.rock =20;
                    break;
                }
            }
            you.ShowWeapon(this.x+31,this.y+70,0.6,-93,4);
            this.txt = "Spikes";
    this.descript = "\n\nHurts Enemys\n"+this.wood+" Wood  | "+this.rock+" Rock";
            this.select = 4;
        break;
        //Windmill
        case 6:
            you.ShowWeapon(this.x+5,this.y+8,0.6,45,5);
            this.select =5;
            if(this.hover === true){
                switch(you.slots[5]){
                   case 1:
                    this.wood= 50;
                    this.rock =10;
                    break;
                    case 2:
                        this.wood= 60;
                        this.rock =20;
                    break;
                    case 3:
                        this.wood= 100;
                        this.rock =50;
                    break;

                }
            }
            this.txt = "Windmill";
    this.descript = "\n\nGains Gold\n"+this.wood+" Wood  | "+this.rock+" Rock";
        break;
        //Trap and Boost
        case 7:
            if(this.hover === true){
                switch(you.slots[6]){
                    case 0:
                        this.wood= 30;
                        this.rock =30;
                         this.txt = "Trap";
    this.descript = "\n\nTraps Creatures\n"+this.wood+" Wood  | "+this.rock+" Rock";
                    break;
                    case 1:
                        this.wood= 5;
                        this.rock =20;
                         this.txt = "Boost";
    this.descript = "\n\nBoosts you\n"+this.wood+" Wood  | "+this.rock+" Rock";
                    break;
                }
            }
            if(you.slots[6]===0){
                you.ShowWeapon(this.x-5,this.y+30,0.6,0,6);
                this.select = 6;
            }
            if(you.slots[6]===1){
                you.ShowWeapon(this.x,this.y+30,0.5,0,7);
                this.select = 7;

            }
        break;
        //other stuff
        case 8:
           Platforming(this.x+30,this.y+30,50,0,you.slots[7]);
           switch(you.slots[7]){
               case 1:
                    this.txt = "Platform";
                    this.descript = "\n\nWalk across water\n"+this.wood+" Wood  | "+this.rock+" Rock";
                    this.wood= 20;
                    this.rock =5;
                break;
                //Healing Pad
                case 2:
                    this.txt = "Heal Pad";
                    this.descript = "\n\nHeals you+mobs\n"+this.wood+" Wood  | "+this.rock+" Rock";
                    this.wood= 30;
                    this.rock =5;
                break;
               //Poison Pad
                case 3:
                    this.txt = "Poison Pad";
                    this.descript = "\n\nPoisons you+mobs\n"+this.wood+" Wood  | "+this.rock+" Rock";
                    this.wood= 30;
                    this.rock =30;
                break;
                
               //Teleporter
                case 4:
                    this.txt = "Teleporter";
                    this.descript = "\n\nteleports you\n"+this.wood+" Wood  | "+this.rock+" Rock";
                    this.health = 200;
                    this.wood= 70;
                    this.rock =70;
                break;
           }
           this.select = 8;
        break;
    }
        
    if(ptorect(mouseX,mouseY,this.x,this.y,this.s,this.s) ){
        this.hover = true;
        cursor(HAND);
        fill(0,0,0,50);
        noStroke();
        rect(this.x,this.y,this.s,this.s,5);
         you.hovered = 4;

    }
    else{
        this.hover = false;
        
    }
    noStroke();
    
    if(this.hover === true){
        fill(0,0,0,100);
        rect(0,0,width/4,width/8,10);
        fill(240, 240, 240);
        textAlign(LEFT);
        textSize(width/30);
        fill(255, 255, 255);
        text(this.txt,width/50,width/24);
        fill(240, 240, 240);
        textSize(width/50);
        text(this.descript,width/50,width/24);
        
    }
    textAlign(CENTER,CENTER);
};

