/************************************************************/
/*Drawing them*/
/************************************************************/
function SwitchAges(types){
    switch(types){
        case 2:
            if(you.age>=2){
                ChooseAxe.draw();
                ChooseBat.draw();
                ChooseSword.draw();   
                ChooseStick.draw();
                ChoosePolearm.draw();
                ChooseDagger.draw();
            }

        break;
        case 3:
            if(you.age>=3){
                Cookie.draw();
                StoneWall.draw();
            }
        break;
        case 4:
            if(you.age>=4){
                Trap.draw();
                Boost.draw();
                
            }        
        break;
        case 5:
            if(you.age>=5){
                Spike2.draw();
                Wind2.draw();
                
            }        
        break;
        
        case 6:
            if(you.age>=6){
                ChooseHammer.draw();
                ChooseShield.draw();    
            }        
        break;
        
        case 7:
            if(you.age>=7){
                platfrm.draw();
                healpad.draw();
                poison.draw();
                teleport.draw();   
                if(you.slots[2]===2){
                    Cheese.draw();
                } else if(you.slots[2]===1){
                    altCookie.draw();
                }
                if(you.slots[3]===2){
                    CastleWall.draw();
                } else
                if(you.slots[3]===1){
                    altStoneWall.draw();
                }
            }
        break;
        case 8:
            if(you.age>=8){
                if(you.slots[0]==="ShortSword"){
                    ChooseKatana.draw();     
                } else if(you.slots[0]==="Axe"){
                    GreatAxe.draw();
                }
                if(you.slots[5]===2){
                    Wind3.draw();
                }
                if(you.slots[5]===1){
                    Wind2.draw();
                }
            }
        break;
        
        case 9:
            if(you.age>=9){
                if(you.slots[4]===2){
                    Spike3.draw();
                    Spike4.draw();
                } else{
                    you.ageSwitch = 10;
                }
            }
        break;
    }

         
    if((you.age-you.ageSwitch+1)>0&&you.ageSwitch<10){
        stext("Select Items:   "+(you.age-you.ageSwitch+1),width/2,height/5,25,0,0,2);    
    }
}

