/************************************************************/
/*The Box with a shadow*/
/************************************************************/
function ShadowBox(x,y,w,h,txt){
    rectMode(CENTER);
    fill(204, 204, 204);
    rect(x,y+h/1.8+h/5,w*1.2,h*3.5,3);
    
    fill(250, 250, 250);
    rect(x,y+h/1.8,w*1.2,h*3.5,3);  
    
    textAlign(CENTER);
    textSize(width/50);
    fill(102, 102, 102);
    text(txt,x,y-h/2);
    
    textAlign(CENTER,CENTER);
}

