function Settings(x,y,w,h,type){
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.type = type;
    this.hover = false;
}
Settings.prototype.draw = function(){
    rectMode(CENTER);
    noStroke();    
    fill(232, 232, 232);
    rect(this.x,this.y,this.w,this.h,3);
    
    textSize(width/43);
    switch(this.type){
        case "delag":
            if(delag === false){fill(199, 199, 199);}
            if(delag === true){fill(128, 128, 128);}
            text("Delag: "+delag,this.x,this.y);
            if(clicktme>0&&this.hover === true){
                   if(delag === true){
                       delag = false;
                   } else{
                       delag = true;
                   }
               } 
        break;
        
        case "Sandbox":
            if(Sandbox === false){fill(199, 199, 199);}
            if(Sandbox === true){fill(128, 128, 128);}
            text("Sandbox: "+Sandbox,this.x,this.y);
            if(clicktme>0&&this.hover === true){
                   if(Sandbox === true){
                       Sandbox = false;
                   } else{
                       Sandbox = true;
                   }
               } 
        break;
        case "Bosses":
            if(Bosses === false){fill(199, 199, 199);}
            if(Bosses === true){fill(128, 128, 128);}
            text("Bosses: "+Bosses,this.x,this.y);
            if(clicktme>0&&this.hover === true){
                   if(Bosses === true){
                       Bosses = false;
                   } else{
                       Bosses = true;
                   }
               } 
        break;
        case "Invinsible":
            if(Invinsible === false){fill(199, 199, 199);}
            if(Invinsible === true){fill(128, 128, 128);}
            text("Invincible: "+Invinsible,this.x,this.y);
            if(clicktme>0&&this.hover === true){
                   if(Invinsible === true){
                       Invinsible = false;
                   } else{
                       Invinsible = true;
                   }
               } 
        break;
    }
    
    if(ptorect(mouseX,mouseY,this.x-this.w/2,this.y-this.h/2,this.w,this.h)){
        cursor(HAND);
        this.hover = true;
        fill(0, 0, 0,40);
        rect(this.x,this.y,this.w,this.h,3);
    }
    else{
        this.hover = false;
    }
    
    
};

