/*Input your name*/
/************************************************************/
function TextBox(x,y,w,h){
    this.txt = "";
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.Input = false;
}
TextBox.prototype.draw = function(){
    rectMode(CENTER);
    noStroke();    
    
    ShadowBox(this.x,this.y,this.w,this.h);
    
    fill(232, 232, 232);
    rect(this.x,this.y,this.w,this.h,3);
    
    
    textSize(width/43);
    if(this.txt.length<=0){
         fill(199, 199, 199);
        text("Enter Name",this.x,this.y);         
    }
    else{
        fill(82, 82, 82);
        text(this.txt,this.x,this.y);        
    }
    
    if(this.Input){
        fill(102, 102, 102,100+cos(frameCount*10)*200);
        rect(this.x+textWidth(this.txt)/2,this.y,1,this.h-5);
    }
    
    rectMode(CORNER);
};
TextBox.prototype.update = function(){
    if(ptorect(mouseX,mouseY,this.x-this.w/2,this.y-this.h/2,this.w,this.h) ){
        cursor(TEXT);
        if(clicktme>0){
            this.Input = true;
        }
    }
    else if(clicktme>0){
        this.Input = false;
    }
    
    if(this.txt.length>0){you.name = this.txt;}
    else{
        you.name = "Unknown";
    }
};
