/************************************************************/
/*Button to buy stuff with*/
/************************************************************/
function BuyBtn(x,y,w,h,id,name,txt,price,type){
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.id = id;
    this.name = name;
    this.txt = txt;
    this.price = price;
    this.hover = false;
    this.type = type;
    
    this.size = 0;
    this.fader = 255;
    
    this.fading = 0;
    
    this.showtexting = "hat";
}
BuyBtn.prototype.draw = function(){

    pushMatrix();
        translate(this.x,this.y);
        rectMode(CENTER);
        fill(0,0,0,50+(this.fader-200));
        noStroke();
        rect(0,0,this.w,this.h);
        textAlign(CENTER,CENTER);
        textSize(width/50);
        
        if(this.price<=0){
            if(this.type === "hat"&&you.hat===this.id){
                fill(252, 207, 73,this.fader);
                text("equipped",0,0);
            }
            else if(this.type === "tail"&&you.tail===this.id){
                fill(252, 207, 73,this.fader);
                text("equipped",0,0);
            } else{
                fill(245, 245, 245,this.fader);
                text("equip",0,0);
            }
        } else{
            fill(247, 195, 64,this.fader);
            text(this.price,0,0);            
        }
        
        textAlign(LEFT,CENTER);
        text(this.name,this.w/2+10,0);
        
        if(this.type === "hat"){
            Accessories(-this.w/2-width/20,0,this.w/170+this.size,0,"Hat",this.id);
        }
        if(this.type === "tail"){
            Accessories(-this.w/2-width/20,0,this.w/170+this.size,0,"Tail",this.id);
        }
        
    popMatrix();
    
    
    textAlign(CENTER,CENTER);
    rectMode(CORNER);
};
BuyBtn.prototype.update = function(){
    if(ptorect(mouseX,mouseY,this.x-this.w/2,this.y-this.h/2,this.w,this.h)){
        cursor(HAND);
        rectMode(CENTER);
        this.hover = true;
        fill(0, 0, 0,40);
        noStroke();
        rect(this.x,this.y,this.w,this.h,3);
   
    }
    else{
        this.hover = false;
    }
    
    if(this.hover === true&&clicktme>0){
        if(this.price>0&&you.gold>=this.price&&this.type === "hat"&&this.showtexting ==="hat"){
            you.gold-=this.price;
            this.price-=this.price;
        } else
        if(this.price>0&&you.gold>=this.price&&this.type === "tail"&&this.showtexting ==="tail"){
            you.gold-=this.price;
            this.price-=this.price;
        }
        
        if(this.type === "hat"&&this.showtexting ==="hat"&&this.price<=0&&you.hat!==this.id){
            you.hat = this.id;
            hats[this.id][1] = 0;
            
        } else if(this.type==="hat"&&this.showtexting ==="hat"&&this.id===you.hat){
            you.hat = 0;
        } else
        if(this.type === "tail"&&this.showtexting ==="tail"&&this.price<=0&&you.tail!==this.id){
            you.tail = this.id;
            tails[this.id][1] = 0;
        } else if(this.type==="tail"&&this.showtexting ==="tail"&&this.id===you.tail){
            you.tail = 0;
        }
    }
    
    this.fading = constrain(this.fading,0,255);
    if(this.hover === true){
        rectMode(CORNER);
        this.fading+=10;
        fill(0,0,0,this.fading/3);
        rect(ww/2-width/4,0,width/2,width/8,3);
        
       
        textSize(ww/50);
        if(this.type === "hat"&&this.showtexting ==="hat"){
             fill(255, 255, 255,this.fading);
            text(this.txt,width/2,width/16);
        } else
        if(this.type === "tail"&&this.showtexting ==="tail"){
             fill(255, 255, 255,this.fading);
            text(this.txt,width/2,width/16);
        }
    }
    else{
        this.fading*=0.5;
    }
};
